  'Mental Health Nursing',
  'This course develops the knowledge, skills, and professional stance needed for safe psychiatric-mental health nursing. Students learn therapeutic communication, psychiatric assessment, mental status examination, milieu care, trauma-informed practice, common psychiatric disorders, psychopharmacology, suicide and violence risk assessment, crisis intervention, substance use care, legal protections, and recovery-oriented transitions. The course emphasizes dignity, least-restrictive care, cultural humility, collaborative safety planning, integrated behavioral health, and simulation-based clinical judgment.',
  $mhnjson${"slug": "mental-health-nursing", "title": "Mental Health Nursing", "description": "This course develops the knowledge, skills, and professional stance needed for safe psychiatric-mental health nursing. Students learn therapeutic communication, psychiatric assessment, mental status examination, milieu care, trauma-informed practice, common psychiatric disorders, psychopharmacology, suicide and violence risk assessment, crisis intervention, substance use care, legal protections, and recovery-oriented transitions. The course emphasizes dignity, least-restrictive care, cultural humility, collaborative safety planning, integrated behavioral health, and simulation-based clinical judgment.", "topics": [{"id": "5022bce6-c74a-4489-9e04-b83181a122db", "type": "topic", "title": "Psychiatric-Mental Health Nursing Role, Recovery, and Therapeutic Use of Self", "description": "Students learn the nurse's role in mental health care, recovery-oriented practice, therapeutic presence, and stigma reduction.", "children": [{"id": "a3c2a70c-9642-457b-8475-dc0fc27b804d", "type": "subtopic", "title": "Professional role", "description": "The point is to understand psychiatric nursing as relational, safety-focused, recovery-oriented care.", "children": [{"id": "3a351510-ae59-4157-8f93-df73304aa557", "type": "concept", "title": "Scope and standards of psychiatric nursing"}, {"id": "a668e7fd-2201-49f7-9297-83b045d20dad", "type": "concept", "title": "Nursing process in behavioral health"}, {"id": "0b362f3a-fae8-4572-84b1-06bf81c02127", "type": "concept", "title": "Advocacy, stigma reduction, and therapeutic presence"}]}, {"id": "e38b2f0b-766b-49c5-9f56-556e01c5caa1", "type": "subtopic", "title": "Recovery model", "description": "Students learn to focus on hope, function, strengths, and patient-defined goals.", "children": [{"id": "180248ed-f9f5-4f49-bf91-b21fc0756e66", "type": "concept", "title": "Recovery versus symptom elimination alone"}, {"id": "d16650ea-c35a-4a32-91c2-40332d601c07", "type": "concept", "title": "Strengths-based planning"}, {"id": "3320b866-8ddc-4cf5-b4e4-c5e8e79ddc4e", "type": "concept", "title": "Peer support and lived-experience perspectives"}]}, {"id": "c4f9b5ac-5ebe-4f37-b395-83f38020da6b", "type": "subtopic", "title": "Therapeutic use of self", "description": "Mental health nursing requires deliberate awareness of self, boundaries, and communication.", "children": [{"id": "5bea516f-700f-4a7d-9e7a-dc7b911f1e08", "type": "concept", "title": "Self-awareness and countertransference basics"}, {"id": "e7c53268-2776-468b-95d0-2efe387a62fd", "type": "concept", "title": "Professional boundaries"}, {"id": "ed2e276d-829f-491b-b319-9a058962dc92", "type": "concept", "title": "Compassion, consistency, and reliability"}]}]}, {"id": "805bc97b-35ca-4e64-94c7-e2a81b34ec3e", "type": "topic", "title": "Therapeutic Communication, Psychiatric Interview, and Mental Status Exam", "description": "This module develops the assessment and communication skills that anchor safe psychiatric nursing care.", "children": [{"id": "4dba9f62-a1b0-464e-a1f4-6a54b362772d", "type": "subtopic", "title": "Therapeutic communication", "description": "Students learn communication techniques that support trust, assessment, and de-escalation.", "children": [{"id": "eb293b77-2306-49ea-b880-a9c393350cdf", "type": "concept", "title": "Open-ended questions, reflection, clarification, and silence"}, {"id": "eddc120e-03fc-4d13-b076-e637d2de5abb", "type": "concept", "title": "Validation without false reassurance"}, {"id": "35276aa9-685c-4c41-a5e0-7f54dec2e9a8", "type": "concept", "title": "Communication blocks and repair"}]}, {"id": "e886a06a-e7d2-4707-8a26-299b6d102417", "type": "subtopic", "title": "Psychiatric interview", "description": "A structured interview helps nurses gather safety, symptom, and functional information.", "children": [{"id": "e85fd16c-702f-40ef-b25e-d50c15da6aa2", "type": "concept", "title": "Presenting concern and history"}, {"id": "60bbf94d-19f9-45a3-8671-a1207dfccf2c", "type": "concept", "title": "Risk, protective factors, substance use, trauma, and supports"}, {"id": "9c903be4-dcdb-464b-aac9-15c0745388f1", "type": "concept", "title": "Cultural and spiritual context"}]}, {"id": "2cadfb4e-f4d5-427d-b78d-abad61e460fb", "type": "subtopic", "title": "Mental status exam", "description": "The MSE organizes observed and reported data into a shared clinical language.", "children": [{"id": "49d2465b-87df-4651-b382-b465acd9de46", "type": "concept", "title": "Appearance, behavior, speech, mood, affect, thought, perception, cognition, insight, and judgment"}, {"id": "424b53cf-454a-4d49-adb8-c2df490e67c8", "type": "concept", "title": "Baseline versus acute change"}, {"id": "4d569541-e387-422c-b85c-84ee97006fd7", "type": "concept", "title": "Documentation and handoff relevance"}]}]}, {"id": "ea9994b5-e57d-46f5-8ae1-7f430840c5cf", "type": "topic", "title": "Milieu Therapy, Safety, De-escalation, and Least-Restrictive Care", "description": "Students learn how inpatient and community environments support safety, autonomy, and healing.", "children": [{"id": "1d97951c-f7ca-4408-9d1f-47a2b81dd8f8", "type": "subtopic", "title": "Therapeutic milieu", "description": "The care environment itself can promote stabilization, structure, and connection.", "children": [{"id": "68ffd998-9bcc-4df3-bd8f-ef615b5be1f2", "type": "concept", "title": "Unit routines, groups, activities, and boundaries"}, {"id": "b0294c95-6609-41ae-965d-27d2409420b9", "type": "concept", "title": "Observation levels and safety checks"}, {"id": "84dffbb6-dcaa-485c-b2ed-f54251d29fdc", "type": "concept", "title": "Environmental safety and ligature risk awareness"}]}, {"id": "424f3f30-28fa-425e-a8cd-a095368b76b5", "type": "subtopic", "title": "De-escalation", "description": "Students learn to reduce agitation while preserving dignity and safety.", "children": [{"id": "7645c2ee-3702-4b7a-8e66-97bb36ce0228", "type": "concept", "title": "Early warning signs"}, {"id": "9e5dac8e-bcac-45ec-bf98-09ba8c416bf0", "type": "concept", "title": "Verbal de-escalation and space management"}, {"id": "cd637c88-20d3-47d1-8aa3-74a27ad50161", "type": "concept", "title": "Trauma-informed choices and collaborative problem-solving"}]}, {"id": "1651a29e-b5b5-4365-809c-5dd3b767d310", "type": "subtopic", "title": "Least-restrictive care", "description": "Psychiatric nursing centers rights and restraint reduction.", "children": [{"id": "117139e9-34d5-4e84-9ff6-c9a6a4656e2f", "type": "concept", "title": "Seclusion and restraint prevention"}, {"id": "4e964fff-92f1-4bcb-bfbd-9990a5d41a2e", "type": "concept", "title": "Emergency intervention criteria"}, {"id": "d30bc7c4-99a6-4e74-ba8c-62e4ff256e2f", "type": "concept", "title": "Debriefing and documentation"}]}]}, {"id": "81251d7c-7e0e-4853-802d-2f530618c72b", "type": "topic", "title": "Anxiety, OCD, Somatic, and Trauma-Related Disorders", "description": "This topic covers common anxiety and trauma presentations with trauma-informed nursing responses.", "children": [{"id": "0444b893-9db0-419d-8cae-1a3248f88047", "type": "subtopic", "title": "Anxiety disorders", "description": "Students learn to distinguish everyday anxiety from impairing clinical anxiety.", "children": [{"id": "9ee6290f-bf72-4797-a19b-22503ebff9f1", "type": "concept", "title": "Generalized anxiety, panic, phobias, and social anxiety"}, {"id": "9491aaec-00bc-49ce-b9cb-2761467b5d34", "type": "concept", "title": "Physiologic symptoms and avoidance"}, {"id": "db05dd91-3818-49f1-987a-fa4c59691726", "type": "concept", "title": "Grounding, breathing, exposure concepts, and patient education"}]}, {"id": "d1f8e197-8ac1-4a2d-91b4-7c2e3014808e", "type": "subtopic", "title": "OCD and somatic symptoms", "description": "These conditions require validation without reinforcing symptoms or rituals.", "children": [{"id": "20ebf28c-c572-4aaf-9984-a1af9917c3e3", "type": "concept", "title": "Obsessions and compulsions"}, {"id": "c966332f-c006-47e3-a288-bcc049295486", "type": "concept", "title": "Somatic symptom and illness anxiety concepts"}, {"id": "06a48262-0366-4ec5-b154-35b2932df2b0", "type": "concept", "title": "CBT/ERP awareness and nursing support"}]}, {"id": "6c07b73c-9061-47ad-ac1b-8234174024cb", "type": "subtopic", "title": "Trauma-related disorders", "description": "Trauma-informed care protects patients from re-traumatization.", "children": [{"id": "6d465d0c-f7d5-499b-a7b4-a537bf1e3fc8", "type": "concept", "title": "Acute stress, PTSD, complex trauma, and dissociation"}, {"id": "c1a3ec33-f913-4bfc-902b-46a96da49115", "type": "concept", "title": "Triggers, flashbacks, and grounding"}, {"id": "da9a07dc-f1e7-4a57-81c0-e9ab286d5c6f", "type": "concept", "title": "Safety, choice, collaboration, and empowerment"}]}]}, {"id": "7120bc02-c42a-416f-a02f-5c08a140f3b9", "type": "topic", "title": "Mood Disorders: Depression, Bipolar Disorder, and Suicide Risk", "description": "Students learn assessment, safety planning, interventions, and medication considerations for mood disorders.", "children": [{"id": "ccfeef31-1f00-497f-a239-780d8edc2ddb", "type": "subtopic", "title": "Depression", "description": "Students learn to assess mood, function, neurovegetative symptoms, and safety.", "children": [{"id": "bcc204db-e405-4f4e-85d2-5d745b2e3799", "type": "concept", "title": "Major depressive disorder symptoms"}, {"id": "30953f14-2f19-4813-bd25-8e9fc0fc94bf", "type": "concept", "title": "Sleep, appetite, energy, concentration, and hopelessness"}, {"id": "31758bc9-120d-4f3b-852b-3b0f884029bf", "type": "concept", "title": "Behavioral activation and support"}]}, {"id": "a832260f-d32a-4bea-9264-8092157e583b", "type": "subtopic", "title": "Bipolar disorder", "description": "Bipolar care requires attention to mood elevation, impulsivity, sleep, and medication adherence.", "children": [{"id": "2e475afc-b9f1-4b43-b21b-4aa405989c80", "type": "concept", "title": "Mania, hypomania, and mixed features"}, {"id": "df6eef67-dd86-4666-9046-71ede29a5f1d", "type": "concept", "title": "Limit setting and low-stimulation environment"}, {"id": "f49d700a-e3f1-4a5e-a5b1-7eb034a1b73d", "type": "concept", "title": "Lithium, anticonvulsants, antipsychotics, and monitoring awareness"}]}, {"id": "fdecd008-b526-406c-b297-aef04f759b47", "type": "subtopic", "title": "Suicide risk in mood disorders", "description": "Suicide assessment is a core nursing safety competency.", "children": [{"id": "6f09a387-db87-4c35-aec5-368f8b6df187", "type": "concept", "title": "Ideation, intent, plan, means, past attempts, and protective factors"}, {"id": "d2be58a1-5142-4cc5-a52c-09bdea81876d", "type": "concept", "title": "Observation, environmental safety, and escalation"}, {"id": "81aeb3c0-0854-49e1-80b4-1634c6c49436", "type": "concept", "title": "Collaborative safety planning"}]}]}, {"id": "73be480d-017e-4ecb-ab6d-ea948700a8ec", "type": "topic", "title": "Schizophrenia and Psychotic Disorders", "description": "This module covers psychosis, reality-based communication, antipsychotic monitoring, and recovery support.", "children": [{"id": "90d472b2-18e6-45d5-b85d-6b9a46af2663", "type": "subtopic", "title": "Psychosis assessment", "description": "Students learn to identify hallucinations, delusions, disorganization, and negative symptoms.", "children": [{"id": "9cc967e6-4a2c-45c8-a540-993cef6359a6", "type": "concept", "title": "Positive and negative symptoms"}, {"id": "a579c304-2de0-482a-aaaa-5156bd43d9b9", "type": "concept", "title": "Command hallucinations and safety risk"}, {"id": "1d677172-ab73-48c7-9942-c1c3aacac0dc", "type": "concept", "title": "Substance- or medical-induced psychosis considerations"}]}, {"id": "8014294e-4f9d-4f3a-af3c-9c8cba028129", "type": "subtopic", "title": "Therapeutic responses", "description": "Nursing care supports reality testing without arguing or shaming.", "children": [{"id": "9e0be7e5-044f-44eb-b99a-fe5043d0aa89", "type": "concept", "title": "Reality-based communication"}, {"id": "81cdcb7d-ee8a-4348-a4eb-545658be54ee", "type": "concept", "title": "Responding to hallucinations and delusions"}, {"id": "8b9369e1-a18c-4b2b-895b-5811168d48ef", "type": "concept", "title": "Reducing stimulation and supporting function"}]}, {"id": "e8e8039f-a300-4d52-8ade-daa64d7e0221", "type": "subtopic", "title": "Long-term recovery", "description": "Psychosis care includes medication, psychosocial support, and relapse prevention.", "children": [{"id": "2684a902-f8ca-40fc-875e-5303c2c50331", "type": "concept", "title": "Antipsychotic adherence and side effects"}, {"id": "832aebc6-7abe-4da6-89d9-adaad9a8a726", "type": "concept", "title": "Early warning signs"}, {"id": "0225ceb4-373e-4e2c-97c2-b26dbab0dd97", "type": "concept", "title": "Family education, housing, and community supports"}]}]}, {"id": "18e263f3-b796-404a-bd4c-367c59410b73", "type": "topic", "title": "Personality Disorders, Emotional Dysregulation, and Boundaries", "description": "Students learn structured, compassionate care for patients with interpersonal instability and high emotional distress.", "children": [{"id": "401363c4-df0d-4b7b-a13a-53765e9b5e70", "type": "subtopic", "title": "Clinical patterns", "description": "Students learn common patterns while avoiding labels that stigmatize patients.", "children": [{"id": "51fdf942-11f5-453f-8081-ef9b51a1852e", "type": "concept", "title": "Borderline, antisocial, narcissistic, and avoidant traits overview"}, {"id": "8ae3d3c4-8f18-4831-9847-2344dc36b295", "type": "concept", "title": "Emotional dysregulation and interpersonal instability"}, {"id": "7f599114-c875-4b68-bd05-490f4cedde43", "type": "concept", "title": "Self-harm and chronic risk considerations"}]}, {"id": "ec47cd1a-9d28-4387-8f05-aebb85100667", "type": "subtopic", "title": "Structured nursing care", "description": "Consistency and boundaries help reduce chaos and improve safety.", "children": [{"id": "0ab4fc69-89a4-4060-89dd-f0b8cda99b93", "type": "concept", "title": "Clear expectations and team consistency"}, {"id": "c92749ab-da7e-4f18-80a0-5ad5c3210412", "type": "concept", "title": "Limit setting and validation"}, {"id": "aa57e685-e4ff-4abd-bfb6-c89a165dd823", "type": "concept", "title": "Splitting, staff communication, and care plans"}]}, {"id": "d4a02f51-613b-484a-81c1-d41f53809703", "type": "subtopic", "title": "Skill-based support", "description": "Nurses reinforce coping and interpersonal skills.", "children": [{"id": "0e0e54f2-ce13-4943-a3b5-4dba116a4a0e", "type": "concept", "title": "DBT-informed skills awareness"}, {"id": "70498a9b-5f53-48cf-9e40-522a2f45fd28", "type": "concept", "title": "Distress tolerance and grounding"}, {"id": "7b9d3798-43d9-41c0-b7b2-73308cd14837", "type": "concept", "title": "Crisis plans and follow-up"}]}]}, {"id": "3ee0c8fe-5b40-4cda-92ff-ef9509591ed6", "type": "topic", "title": "Substance Use Disorders and Co-Occurring Mental Health Conditions", "description": "This topic integrates addiction, withdrawal safety, harm reduction, recovery, and co-occurring psychiatric care.", "children": [{"id": "eb0a4922-7b91-466b-9b79-075a565cac93", "type": "subtopic", "title": "Addiction foundations", "description": "Students learn substance use as a health condition shaped by biology, behavior, environment, and stigma.", "children": [{"id": "d19af004-43e7-4bbd-9466-51921a91fbbe", "type": "concept", "title": "Tolerance, withdrawal, craving, and relapse"}, {"id": "7f555f9e-17a5-47a2-a100-5e48ee4a275c", "type": "concept", "title": "Alcohol, opioids, stimulants, sedatives, and cannabis overview"}, {"id": "8e2e49eb-a76d-4c0b-93a1-0ed36c5e5185", "type": "concept", "title": "Stages of change and motivational interviewing awareness"}]}, {"id": "4a822dcb-7650-45f9-bc11-d40ba15febe9", "type": "subtopic", "title": "Withdrawal and safety", "description": "Withdrawal can be medically dangerous and requires careful monitoring.", "children": [{"id": "1e39b937-0982-469a-ba8d-fa41b0663a1a", "type": "concept", "title": "Alcohol withdrawal and seizure risk"}, {"id": "7ec6b383-5392-4749-8c0b-b1554f7a35e6", "type": "concept", "title": "Opioid withdrawal and comfort care"}, {"id": "6d826594-77eb-4d50-b04a-695bd8c2deae", "type": "concept", "title": "CIWA/COWS awareness and escalation"}]}, {"id": "51c7d3e4-2826-407e-8848-213f10627a7c", "type": "subtopic", "title": "Integrated recovery care", "description": "Many patients live with both substance use and mental health conditions.", "children": [{"id": "2d70c72e-433d-4835-ab1a-2784ed63de74", "type": "concept", "title": "Co-occurring disorders"}, {"id": "574b33a3-61d5-4010-a78a-b22fa1be3429", "type": "concept", "title": "Medication-assisted treatment awareness"}, {"id": "6a41d23c-f096-4cde-bbc9-f039507b08a0", "type": "concept", "title": "Harm reduction, relapse prevention, and referral"}]}]}, {"id": "b197be68-4b2a-43f0-8cb5-00981154baee", "type": "topic", "title": "Eating Disorders and Body Image-Related Conditions", "description": "Students learn medical and psychiatric nursing priorities for eating disorders and related risk states.", "children": [{"id": "32ca1b1c-ef75-418f-a526-cd1ae97c13b7", "type": "subtopic", "title": "Eating disorder assessment", "description": "Students learn to recognize medical and psychiatric risk in eating disorders.", "children": [{"id": "5a77fc5f-e8ee-445d-a664-db2e71acae42", "type": "concept", "title": "Anorexia nervosa, bulimia nervosa, and binge-eating disorder"}, {"id": "e9bb85c1-8699-4fa0-bdb9-500ed4a89d38", "type": "concept", "title": "Vital signs, weight trends, labs, and purging behaviors"}, {"id": "429c9ea1-d8ff-44b6-979a-a5b9c717a739", "type": "concept", "title": "Body image, shame, secrecy, and control"}]}, {"id": "0f606777-2936-40bc-bf58-8f5833119761", "type": "subtopic", "title": "Medical safety", "description": "Eating disorders can create serious physiologic instability.", "children": [{"id": "4f14a8d2-bef8-4287-a3f0-b64298680e22", "type": "concept", "title": "Electrolyte imbalance and cardiac risk"}, {"id": "af967bd3-3601-4008-9984-e37fe382ba4a", "type": "concept", "title": "Refeeding syndrome awareness"}, {"id": "e390fb6d-06b8-4370-8e3c-ebb591c85b14", "type": "concept", "title": "Observation and meal support"}]}, {"id": "729637e8-b609-4bd5-88c1-955982b2e65c", "type": "subtopic", "title": "Therapeutic care", "description": "Nursing care supports safety while preserving dignity.", "children": [{"id": "471633c4-1eff-4e7e-8a2f-ef7f16ba9eb9", "type": "concept", "title": "Nonjudgmental communication"}, {"id": "50ab95b7-a521-41f7-a558-4def877cb90d", "type": "concept", "title": "Family-based and interdisciplinary treatment awareness"}, {"id": "24ec0bb0-9101-46d9-b571-8de68d51dbe2", "type": "concept", "title": "Relapse prevention and discharge supports"}]}]}, {"id": "35d560fe-4d2c-4feb-b3a4-5ae8925e76ba", "type": "topic", "title": "Psychopharmacology and Medication Safety in Mental Health Nursing", "description": "This module links psychotropic medication classes to monitoring, side effects, adherence, and patient teaching.", "children": [{"id": "db05182e-698f-41fc-aace-8cc924827e0c", "type": "subtopic", "title": "Medication classes", "description": "Students connect psychiatric symptoms to medication mechanisms and nursing monitoring.", "children": [{"id": "d65d98a8-3996-4607-b7ec-4880a213ad85", "type": "concept", "title": "Antidepressants and anxiolytics"}, {"id": "64cb80ce-136b-40de-a5e4-c8bb21dc3707", "type": "concept", "title": "Mood stabilizers and antipsychotics"}, {"id": "1a459c0e-88bd-4c69-be7f-67bcfd6e21e2", "type": "concept", "title": "Stimulants, sedatives, and medications for substance use"}]}, {"id": "8997b3de-6c36-4695-b3bc-2bbf6cd42750", "type": "subtopic", "title": "Adverse effects and monitoring", "description": "Psychotropic safety requires knowing what to watch for and when to escalate.", "children": [{"id": "1af1591f-3fe7-487a-86c1-e3c5112d5a1d", "type": "concept", "title": "Serotonin syndrome, neuroleptic malignant syndrome, EPS, metabolic effects, and QT risk"}, {"id": "a45f39aa-d248-4935-9d53-f7de1431741c", "type": "concept", "title": "Lithium levels and toxicity awareness"}, {"id": "62cfa521-0bfd-4ecb-9875-b67564d33d7f", "type": "concept", "title": "Pregnancy, older adults, interactions, and polypharmacy"}]}, {"id": "71472c65-adcb-428a-b18d-4cf564896f12", "type": "subtopic", "title": "Adherence and teaching", "description": "Medication success depends on shared understanding and collaborative care.", "children": [{"id": "f93e5370-6b9a-43e9-b19e-a4cf2deb2883", "type": "concept", "title": "Side-effect teaching"}, {"id": "6e7221d3-fd27-45c0-b25c-aff95fca3130", "type": "concept", "title": "Stigma and medication beliefs"}, {"id": "d76b363a-9175-4a62-a063-3bdebc57fe23", "type": "concept", "title": "Coordination with prescribers and primary care"}]}]}, {"id": "90d4e928-de3b-4385-b684-c954bf393de1", "type": "topic", "title": "Crisis Intervention, Suicide Assessment, Violence Risk, and Safety Planning", "description": "Students learn immediate stabilization, risk assessment, collaborative safety planning, and mandated response basics.", "children": [{"id": "9b2989a6-a606-4688-9da3-2bc00b502d4a", "type": "subtopic", "title": "Crisis stabilization", "description": "The aim is immediate safety, emotional containment, and connection to next supports.", "children": [{"id": "3552e047-8bef-4218-88c1-14381157f5fc", "type": "concept", "title": "Crisis assessment"}, {"id": "cb5e2f7d-34e0-4478-bae0-2479b54048f3", "type": "concept", "title": "Psychological first aid awareness"}, {"id": "56ea1717-fe2b-4af6-8e77-56fe246b82a6", "type": "concept", "title": "Grounding, coping, and support mobilization"}]}, {"id": "668429bd-15dc-4b87-9549-bb3b9d5ea9ac", "type": "subtopic", "title": "Suicide assessment", "description": "Students learn direct, compassionate, structured suicide inquiry.", "children": [{"id": "43ed6f89-1a02-488a-974a-335bb3a92722", "type": "concept", "title": "Ideation, plan, intent, means, attempts, and protective factors"}, {"id": "dd241832-0929-49a6-b39d-638a9d333946", "type": "concept", "title": "Safety planning and lethal-means counseling awareness"}, {"id": "94cab7ae-e243-457c-8078-5fccecd5f5e8", "type": "concept", "title": "988 Lifeline and emergency referral"}]}, {"id": "26aa4bd1-ca44-4ce3-8244-762b4b548703", "type": "subtopic", "title": "Violence and mandated response", "description": "Nurses must balance safety, rights, confidentiality, and legal duties.", "children": [{"id": "6019930e-e0a3-4886-b06f-0ffd071e4932", "type": "concept", "title": "Threat assessment and duty-to-protect concepts"}, {"id": "034c1a34-5e1e-44e2-827d-7b289ff23354", "type": "concept", "title": "Abuse, neglect, and mandated reporting basics"}, {"id": "e14cbed5-a478-498f-844d-068b24a746ec", "type": "concept", "title": "Documentation and team escalation"}]}]}, {"id": "de3eb63d-06bf-4667-a950-f97bf244c867", "type": "topic", "title": "Group, Family, and Milieu-Based Interventions", "description": "This topic introduces therapeutic groups, family engagement, psychoeducation, and structured unit routines.", "children": [{"id": "5b48c763-5d8c-417c-8274-7e65f71c0739", "type": "subtopic", "title": "Group work", "description": "Groups help patients practice skills, receive support, and build insight.", "children": [{"id": "3e4c9d1c-0665-46f9-9028-35e5e9f19a9a", "type": "concept", "title": "Psychoeducation groups"}, {"id": "96dc27c7-8e0f-49cc-a202-22bb4072986c", "type": "concept", "title": "Skills and coping groups"}, {"id": "8d8b2801-b222-43bb-a2a5-3ef9bc90a30d", "type": "concept", "title": "Group norms, confidentiality, and participation"}]}, {"id": "fb226550-ef12-49f0-b737-c36807acf735", "type": "subtopic", "title": "Family engagement", "description": "Families and supports often shape recovery and safety after discharge.", "children": [{"id": "facb3aa1-be17-44f1-900c-1ac823ede18f", "type": "concept", "title": "Family psychoeducation"}, {"id": "8aada4db-9a25-487e-9c3b-6faf09301af9", "type": "concept", "title": "Boundaries, consent, and confidentiality"}, {"id": "3e2e0f85-caae-4fad-b7a8-dfdcc8186321", "type": "concept", "title": "Caregiver stress and resource referral"}]}, {"id": "c139cc2a-9968-4c39-a6d1-6ce985f62794", "type": "subtopic", "title": "Milieu interventions", "description": "Daily structure turns the care environment into a therapeutic tool.", "children": [{"id": "eb3c76f1-4fe8-42b6-adda-803208662a0b", "type": "concept", "title": "Activity scheduling"}, {"id": "6caeb777-a86d-4618-8730-4a6867084979", "type": "concept", "title": "Peer support and unit culture"}, {"id": "a9004a09-8c3a-4dea-94f2-2631bf3bc9d5", "type": "concept", "title": "Behavior plans and reinforcement"}]}]}, {"id": "5397c322-5d0c-48fe-a369-b014d737a3fc", "type": "topic", "title": "Legal, Ethical, Cultural, and Human-Rights Issues in Psychiatric Care", "description": "Students learn patient rights, involuntary care, privacy, consent, equity, and ethical dilemmas in mental health settings.", "children": [{"id": "e05d8e77-f048-4cd5-ab3b-c3f048a73eab", "type": "subtopic", "title": "Patient rights", "description": "Psychiatric care must protect rights, dignity, privacy, and informed consent.", "children": [{"id": "d867acf9-2064-4b87-8c37-73ce028b82bf", "type": "concept", "title": "Voluntary and involuntary admission basics"}, {"id": "9eb6a68d-e8b5-41e8-8443-ddbee856bdad", "type": "concept", "title": "Right to treatment and refusal concepts"}, {"id": "c01440ca-da1e-43d9-8263-2c7d5cd56d8c", "type": "concept", "title": "Confidentiality and documentation"}]}, {"id": "be3b4213-1ed1-49d0-9058-850c2d7fb175", "type": "subtopic", "title": "Ethical dilemmas", "description": "Students learn to reason through autonomy, safety, coercion, and beneficence.", "children": [{"id": "d9255800-4638-489b-9fb7-76a11dbf716b", "type": "concept", "title": "Least-restrictive alternative"}, {"id": "5f137508-fb45-486c-90eb-729d8d55253f", "type": "concept", "title": "Capacity and consent awareness"}, {"id": "935b076d-959f-4ae4-a67a-68690c437a85", "type": "concept", "title": "Moral distress and ethics consultation"}]}, {"id": "d1d5a97a-2aa9-41af-8eee-9a93864d9f90", "type": "subtopic", "title": "Cultural and structural context", "description": "Mental health nursing must account for culture, oppression, and access barriers.", "children": [{"id": "8aefa617-1f87-4992-ba79-14fc00cc7846", "type": "concept", "title": "Cultural formulation awareness"}, {"id": "34955187-4aac-4d2a-a7b3-e9f20591d7a1", "type": "concept", "title": "Racism, stigma, poverty, and criminalization"}, {"id": "6f0ce568-adb4-409a-a288-feb2f7d9e30a", "type": "concept", "title": "Language access and inclusive care"}]}]}, {"id": "c81ef282-076a-4437-8294-40cb172ce0c3", "type": "topic", "title": "Integrated Behavioral Health, Community Resources, and Care Transitions", "description": "This module connects inpatient, outpatient, primary care, community, crisis, and recovery supports.", "children": [{"id": "cb459834-8628-4f4f-90fa-9dd7ccce6470", "type": "subtopic", "title": "Continuum of care", "description": "Patients move across inpatient, outpatient, crisis, primary care, and community settings.", "children": [{"id": "221fe4af-b235-4318-8d52-2a3ac75f36e0", "type": "concept", "title": "Levels of care"}, {"id": "50608ee9-66c6-4552-915e-73e21da4bb09", "type": "concept", "title": "Partial hospitalization, intensive outpatient, and community programs"}, {"id": "3428489f-9ddc-4568-b787-9ea54c6591f6", "type": "concept", "title": "Primary care and integrated behavioral health"}]}, {"id": "ff55be12-989f-4dbb-a510-3cb288aeaa3a", "type": "subtopic", "title": "Community resources", "description": "Nurses should know how to connect patients to practical support.", "children": [{"id": "e951a1a8-9ca9-483c-a716-843bf4a58ca9", "type": "concept", "title": "NAMI, SAMHSA, 988, peer support, and treatment locators"}, {"id": "fe28321f-1850-4579-a8d3-6d64ca527e7f", "type": "concept", "title": "Housing, food, transportation, and benefits referrals"}, {"id": "7ed7a2a0-44ef-42d0-b5c3-5062c192d75e", "type": "concept", "title": "Warm handoffs and follow-up"}]}, {"id": "7b6f6139-0c06-4bf2-808b-240a1857f5bc", "type": "subtopic", "title": "Discharge planning", "description": "Transitions are high-risk moments for relapse and suicide.", "children": [{"id": "56874267-61cb-4e94-8849-0a1135e125b0", "type": "concept", "title": "Medication and appointment planning"}, {"id": "6a8a8696-96de-4055-afb3-c9ec4e16ac60", "type": "concept", "title": "Safety plan and crisis plan"}, {"id": "81b482b3-20df-4cf9-9e1b-10bea8ba54b2", "type": "concept", "title": "Family/support involvement and barriers"}]}]}, {"id": "14c0f478-2803-4dae-8c8d-a36bdfce15f4", "type": "topic", "title": "Mental Health Nursing Simulation, Case Formulation, and Reflective Portfolio", "description": "Students synthesize assessment, communication, safety, diagnosis-aware planning, medication monitoring, and reflection.", "children": [{"id": "3b652d9e-6cba-454c-8220-9a3d665c7755", "type": "subtopic", "title": "Case formulation", "description": "Students synthesize symptoms, strengths, risks, culture, and environment into a nursing plan.", "children": [{"id": "9e8c2deb-25d6-4d2b-9d63-6818dfe1eef3", "type": "concept", "title": "Biopsychosocial formulation"}, {"id": "01c62210-4c13-4e0e-bf58-1426c2f49541", "type": "concept", "title": "Priority nursing diagnoses and outcomes"}, {"id": "98a93819-ebfc-47de-867b-059a86e39092", "type": "concept", "title": "Safety and recovery goals"}]}, {"id": "5c1fa9ba-b03e-4137-b8df-105fdd60d027", "type": "subtopic", "title": "Simulation performance", "description": "Simulation builds communication and safety habits under realistic pressure.", "children": [{"id": "f21a5034-61bf-45d1-bb46-dbffbf47e43d", "type": "concept", "title": "Psychiatric interview and MSE"}, {"id": "0eae1cee-1593-4392-83ac-f2e8f7d1224b", "type": "concept", "title": "De-escalation and suicide assessment"}, {"id": "fee5fd0b-c84a-41c3-8e5b-f4304a8ed937", "type": "concept", "title": "SBAR, handoff, and documentation"}]}, {"id": "66a11046-8c3a-4659-8034-583e988d9d12", "type": "subtopic", "title": "Reflective portfolio", "description": "Reflection helps students use self-awareness and evidence to improve practice.", "children": [{"id": "a7905823-5124-4396-a8a5-fb464996063e", "type": "concept", "title": "Therapeutic use of self reflection"}, {"id": "6190e06d-099d-4966-8306-5fd37919bc3e", "type": "concept", "title": "Bias and stigma audit"}, {"id": "59011dca-e685-4864-be33-1f3e613083f1", "type": "concept", "title": "Personal plan for resilience and professional growth"}]}]}], "dbBacked": true}$mhnjson$::jsonb,
