update public.learning_paths
set
  title = 'Mental Health Nursing',
  goal = 'Mental Health Nursing',
  summary = 'This course develops the knowledge, skills, and professional stance needed for safe psychiatric-mental health nursing. Students learn therapeutic communication, psychiatric assessment, mental status examination, milieu care, trauma-informed practice, common psychiatric disorders, psychopharmacology, suicide and violence risk assessment, crisis intervention, substance use care, legal protections, and recovery-oriented transitions. The course emphasizes dignity, least-restrictive care, cultural humility, collaborative safety planning, integrated behavioral health, and simulation-based clinical judgment.',
  data = $mhnjson${"slug": "mental-health-nursing", "title": "Mental Health Nursing", "description": "This course develops the knowledge, skills, and professional stance needed for safe psychiatric-mental health nursing. Students learn therapeutic communication, psychiatric assessment, mental status examination, milieu care, trauma-informed practice, common psychiatric disorders, psychopharmacology, suicide and violence risk assessment, crisis intervention, substance use care, legal protections, and recovery-oriented transitions. The course emphasizes dignity, least-restrictive care, cultural humility, collaborative safety planning, integrated behavioral health, and simulation-based clinical judgment.", "topics": [{"id": "5022bce6-c74a-4489-9e04-b83181a122db", "type": "topic", "title": "Psychiatric-Mental Health Nursing Role, Recovery, and Therapeutic Use of Self", "description": "Students learn the nurse's role in mental health care, recovery-oriented practice, therapeutic presence, and stigma reduction.", "children": [{"id": "a3c2a70c-9642-457b-8475-dc0fc27b804d", "type": "subtopic", "title": "Professional role", "description": "The point is to understand psychiatric nursing as relational, safety-focused, recovery-oriented care.", "children": [{"id": "3a351510-ae59-4157-8f93-df73304aa557", "type": "concept", "title": "Scope and standards of psychiatric nursing"}, {"id": "a668e7fd-2201-49f7-9297-83b045d20dad", "type": "concept", "title": "Nursing process in behavioral health"}, {"id": "0b362f3a-fae8-4572-84b1-06bf81c02127", "type": "concept", "title": "Advocacy, stigma reduction, and therapeutic presence"}]}, {"id": "e38b2f0b-766b-49c5-9f56-556e01c5caa1", "type": "subtopic", "title": "Recovery model", "description": "Students learn to focus on hope, function, strengths, and patient-defined goals.", "children": [{"id": "180248ed-f9f5-4f49-bf91-b21fc0756e66", "type": "concept", "title": "Recovery versus symptom elimination alone"}, {"id": "d16650ea-c35a-4a32-91c2-40332d601c07", "type": "concept", "title": "Strengths-based planning"}, {"id": "3320b866-8ddc-4cf5-b4e4-c5e8e79ddc4e", "type": "concept", "title": "Peer support and lived-experience perspectives"}]}, {"id": "c4f9b5ac-5ebe-4f37-b395-83f38020da6b", "type": "subtopic", "title": "Therapeutic use of self", "description": "Mental health nursing requires deliberate awareness of self, boundaries, and communication.", "children": [{"id": "5bea516f-700f-4a7d-9e7a-dc7b911f1e08", "type": "concept", "title": "Self-awareness and countertransference basics"}, {"id": "e7c53268-2776-468b-95d0-2efe387a62fd", "type": "concept", "title": "Professional boundaries"}, {"id": "ed2e276d-829f-491b-b319-9a058962dc92", "type": "concept", "title": "Compassion, consistency, and reliability"}]}]}, {"id": "805bc97b-35ca-4e64-94c7-e2a81b34ec3e", "type": "topic", "title": "Therapeutic Communication, Psychiatric Interview, and Mental Status Exam", "description": "This module develops the assessment and communication skills that anchor safe psychiatric nursing care.", "children": [{"id": "4dba9f62-a1b0-464e-a1f4-6a54b362772d", "type": "subtopic", "title": "Therapeutic communication", "description": "Students learn communication techniques that support trust, assessment, and de-escalation.", "children": [{"id": "eb293b77-2306-49ea-b880-a9c393350cdf", "type": "concept", "title": "Open-ended questions, reflection, clarification, and silence"}, {"id": "eddc120e-03fc-4d13-b076-e637d2de5abb", "type": "concept", "title": "Validation without false reassurance"}, {"id": "35276aa9-685c-4c41-a5e0-7f54dec2e9a8", "type": "concept", "title": "Communication blocks and repair"}]}, {"id": "e886a06a-e7d2-4707-8a26-299b6d102417", "type": "subtopic", "title": "Psychiatric interview", "description": "A structured interview helps nurses gather safety, symptom, and functional information.", "children": [{"id": "e85fd16c-702f-40ef-b25e-d50c15da6aa2", "type": "concept", "title": "Presenting concern and history"}, {"id": "60bbf94d-19f9-45a3-8671-a1207dfccf2c", "type": "concept", "title": "Risk, protective factors, substance use, trauma, and supports"}, {"id": "9c903be4-dcdb-464b-aac9-15c0745388f1", "type": "concept", "title": "Cultural and spiritual context"}]}, {"id": "2cadfb4e-f4d5-427d-b78d-abad61e460fb", "type": "subtopic", "title": "Mental status exam", "description": "The MSE organizes observed and reported data into a shared clinical language.", "children": [{"id": "49d2465b-87df-4651-b382-b465acd9de46", "type": "concept", "title": "Appearance, behavior, speech, mood, affect, thought, perception, cognition, insight, and judgment"}, {"id": "424b53cf-454a-4d49-adb8-c2df490e67c8", "type": "concept", "title": "Baseline versus acute change"}, {"id": "4d569541-e387-422c-b85c-84ee97006fd7", "type": "concept", "title": "Documentation and handoff relevance"}]}]}, {"id": "ea9994b5-e57d-46f5-8ae1-7f430840c5cf", "type": "topic", "title": "Milieu Therapy, Safety, De-escalation, and Least-Restrictive Care", "description": "Students learn how inpatient and community environments support safety, autonomy, and healing.", "children": [{"id": "1d97951c-f7ca-4408-9d1f-47a2b81dd8f8", "type": "subtopic", "title": "Therapeutic milieu", "description": "The care environment itself can promote stabilization, structure, and connection.", "children": [{"id": "68ffd998-9bcc-4df3-bd8f-ef615b5be1f2", "type": "concept", "title": "Unit routines, groups, activities, and boundaries"}, {"id": "b0294c95-6609-41ae-965d-27d2409420b9", "type": "concept", "title": "Observation levels and safety checks"}, {"id": "84dffbb6-dcaa-485c-b2ed-f54251d29fdc", "type": "concept", "title": "Environmental safety and ligature risk awareness"}]}, {"id": "424f3f30-28fa-425e-a8cd-a095368b76b5", "type": "subtopic", "title": "De-escalation", "description": "Students learn to reduce agitation while preserving dignity and safety.", "children": [{"id": "7645c2ee-3702-4b7a-8e66-97bb36ce0228", "type": "concept", "title": "Early warning signs"}, {"