49295486", "type": "concept", "title": "Somatic symptom and illness anxiety concepts"}, {"id": "06a48262-0366-4ec5-b154-35b2932df2b0", "type": "concept", "title": "CBT/ERP awareness and nursing support"}]}, {"id": "6c07b73c-9061-47ad-ac1b-8234174024cb", "type": "subtopic", "title": "Trauma-related disorders", "description": "Trauma-informed care protects patients from re-traumatization.", "children": [{"id": "6d465d0c-f7d5-499b-a7b4-a537bf1e3fc8", "type": "concept", "title": "Acute stress, PTSD, complex trauma, and dissociation"}, {"id": "c1a3ec33-f913-4bfc-902b-46a96da49115", "type": "concept", "title": "Triggers, flashbacks, and grounding"}, {"id": "da9a07dc-f1e7-4a57-81c0-e9ab286d5c6f", "type": "concept", "title": "Safety, choice, collaboration, and empowerment"}]}]}, {"id": "7120bc02-c42a-416f-a02f-5c08a140f3b9", "type": "topic", "title": "Mood Disorders: Depression, Bipolar Disorder, and Suicide Risk", "description": "Students learn assessment, safety planning, interventions, and medication considerations for mood disorders.", "children": [{"id": "ccfeef31-1f00-497f-a239-780d8edc2ddb", "type": "subtopic", "title": "Depression", "description": "Students learn to assess mood, function, neurovegetative symptoms, and safety.", "children": [{"id": "bcc204db-e405-4f4e-85d2-5d745b2e3799", "type": "concept", "title": "Major depressive disorder symptoms"}, {"id": "30953f14-2f19-4813-bd25-8e9fc0fc94bf", "type": "concept", "title": "Sleep, appetite, energy, concentration, and hopelessness"}, {"id": "31758bc9-120d-4f3b-852b-3b0f884029bf", "type": "concept", "title": "Behavioral activation and support"}]}, {"id": "a832260f-d32a-4bea-9264-8092157e583b", "type": "subtopic", "title": "Bipolar disorder", "description": "Bipolar care requires attention to mood elevation, impulsivity, sleep, and medication adherence.", "children": [{"id": "2e475afc-b9f1-4b43-b21b-4aa405989c80", "type": "concept", "title": "Mania, hypomania, and mixed features"}, {"id": "df6eef67-dd86-4666-9046-71ede29a5f1d", "type": "concept", "title": "Limit setting and low-stimulation environment"}, {"id": "f49d700a-e3f1-4a5e-a5b1-7eb034a1b73d", "type": "concept", "title": "Lithium, anticonvulsants, antipsychotics, and monitoring awareness"}]}, {"id": "fdecd008-b526-406c-b297-aef04f759b47", "type": "subtopic", "title": "Suicide risk in mood disorders", "description": "Suicide assessment is a core nursing safety competency.", "children": [{"id": "6f09a387-db87-4c35-aec5-368f8b6df187", "type": "concept", "title": "Ideation, intent, plan, means, past attempts, and protective factors"}, {"id": "d2be58a1-5142-4cc5-a52c-09bdea81876d", "type": "concept", "title": "Observation, environmental safety, and escalation"}, {"id": "81aeb3c0-0854-49e1-80b4-1634c6c49436", "type": "concept", "title": "Collaborative safety planning"}]}]}, {"id": "73be480d-017e-4ecb-ab6d-ea948700a8ec", "type": "topic", "title": "Schizophrenia and Psychotic Disorders", "description": "This module covers psychosis, reality-based communication, antipsychotic monitoring, and recovery support.", "children": [{"id": "90d472b2-18e6-45d5-b85d-6b9a46af2663", "type": "subtopic", "title": "Psychosis assessment", "description": "Students learn to identify hallucinations, delusions, disorganization, and negative symptoms.", "children": [{"id": "9cc967e6-4a2c-45c8-a540-993cef6359a6", "type": "concept", "title": "Positive and negative symptoms"}, {"id": "a579c304-2de0-482a-aaaa-5156bd43d9b9", "type": "concept", "title": "Command hallucinations and safety risk"}, {"id": "1d677172-ab73-48c7-9942-c1c3aacac0dc", "type": "concept", "title": "Substance- or medical-induced psychosis considerations"}]}, {"id": "8014294e-4f9d-4f3a-af3c-9c8cba028129", "type": "subtopic", "title": "Therapeutic responses", "description": "Nursing care supports reality testing without arguing or shaming.", "children": [{"id": "9e0be7e5-044f-44eb-b99a-fe5043d0aa89", "type": "concept", "title": "Reality-based communication"}, {"id": "81cdcb7d-ee8a-4348-a